// Split brands into individual items for per-brand Meta API calls
// Attach projects + scripts as context for later nodes
const brandsResp = $('Fetch Brands with Ad Accounts').first().json;
const projectsResp = $('Fetch All Projects').first().json;
const scriptsResp = $input.first().json;

// Determine params source — try both, use whichever ran
let params = { brand_filter: '', source: 'unknown' };
try { params = $('Extract Webhook Params').first().json; } catch(e) {}
try { const sp = $('Schedule Params').first().json; if (sp && sp.source === 'schedule') params = sp; } catch(e) {}

const brands = (brandsResp.records || []).map(r => ({
  id: r.id,
  brand_name: (r.fields || {}).brand_name || '',
  ad_account_id: (r.fields || {}).ad_account_id || '',
  industry: (r.fields || {}).industry || ''
})).filter(b => b.ad_account_id);

const brandFilter = (params.brand_filter || '').toLowerCase();
const filtered = brandFilter
  ? brands.filter(b => b.brand_name.toLowerCase().includes(brandFilter))
  : brands;

if (filtered.length === 0) {
  return [{ json: {
    brandCount: 0,
    brand_name: 'N/A',
    ad_account_id: '',
    source: params.source,
    slackMsg: ':warning: *Performance Sync — No Brands to Process*\nNo brands have `ad_account_id` configured. Add Meta ad account IDs to the Brands table.',
    allProjects: '[]',
    allScripts: '[]'
  } }];
}

// Parse projects and scripts once
const allProjects = (projectsResp.records || []).map(r => ({
  id: r.id,
  project_name: (r.fields || {}).project_name || (r.fields || {}).client_code || '',
  brand_name: (r.fields || {}).brand_name || '',
  brand_id: (r.fields || {}).brand_id || []
}));

const allScripts = (scriptsResp.records || []).map(r => ({
  id: r.id,
  script_number: (r.fields || {}).script_number || '',
  hook: (r.fields || {}).hook || '',
  hook_1: (r.fields || {}).hook_1 || '',
  hook_2: (r.fields || {}).hook_2 || '',
  hook_3: (r.fields || {}).hook_3 || '',
  full_script: ((r.fields || {}).full_script || '').substring(0, 500),
  concept_id: (r.fields || {}).concept_id || [],
  project_id: (r.fields || {}).project_id || [],
  existing_ad_id: (r.fields || {}).meta_ad_id || ''
}));

// Build date range for Meta API (last 30 days)
const now = new Date();
const since = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
const sinceStr = since.toISOString().split('T')[0];
const untilStr = now.toISOString().split('T')[0];

return filtered.map(b => ({ json: {
  brandCount: filtered.length,
  brand_id: b.id,
  brand_name: b.brand_name,
  industry: b.industry,
  ad_account_id: b.ad_account_id,
  since: sinceStr,
  until: untilStr,
  source: params.source,
  allProjects: JSON.stringify(allProjects),
  allScripts: JSON.stringify(allScripts)
} }));

// ============================================================
// Pattern-match ALL brands, output ONE combined item
// This prevents n8n branch-merge double-execution
// ============================================================
const inputs = $input.all();
const contexts = $('Split Brands + Attach Context').all();
const brandResults = [];
let totalAds = 0;
let totalScripts = 0;
const allUnmatchedSections = [];

for (let idx = 0; idx < inputs.length; idx++) {
  const metaResp = inputs[idx].json;
  const brandCtx = contexts[idx]?.json || contexts[0].json;
  const brandId = brandCtx.brand_id;
  const brandName = brandCtx.brand_name;
  const brandIndustry = brandCtx.industry || '';
  const allProjects = JSON.parse(brandCtx.allProjects || '[]');
  const allScripts = JSON.parse(brandCtx.allScripts || '[]');

  const brandProjects = allProjects.filter(p => {
    if (p.brand_id && Array.isArray(p.brand_id) && p.brand_id.length > 0) return p.brand_id.includes(brandId);
    return p.brand_name && p.brand_name.toLowerCase() === brandName.toLowerCase();
  });
  const projectIds = brandProjects.map(p => p.id);
  const brandScripts = allScripts.filter(s => {
    const pids = Array.isArray(s.project_id) ? s.project_id : [s.project_id];
    return pids.some(pid => projectIds.includes(pid));
  });

  const adsData = metaResp.data || [];
  totalAds += adsData.length;
  totalScripts += brandScripts.length;

  if (adsData.length === 0 || brandScripts.length === 0) {
    brandResults.push({ brand_name: brandName, industry: brandIndustry, status: adsData.length === 0 ? 'no_ads' : 'no_scripts', adsCount: adsData.length, scriptsCount: brandScripts.length, matched: [], unmatchedAds: [], brandScripts: [] });
    continue;
  }

  const ads = adsData.map(ad => {
    const actions = ad.actions || []; const actionValues = ad.action_values || [];
    const purchases = actions.find(a => a.action_type === 'purchase') || {};
    const revenue = actionValues.find(a => a.action_type === 'purchase') || {};
    const spend = parseFloat(ad.spend || 0); const rev = parseFloat(revenue.value || 0);
    return { ad_id: ad.ad_id, ad_name: ad.ad_name || '', spend, impressions: parseInt(ad.impressions || 0), clicks: parseInt(ad.clicks || 0), ctr: parseFloat(ad.ctr || 0), roas: spend > 0 ? rev / spend : 0 };
  });

  const matched = []; const unmatchedAds = [];
  for (const ad of ads) {
    const name = ad.ad_name; let found = false;
    const alreadyLinked = brandScripts.find(s => s.existing_ad_id === ad.ad_id);
    if (alreadyLinked) { matched.push({ ad, script: alreadyLinked, method: 'existing' }); continue; }
    const numMatch = name.match(/(?:\[S[- ]?(\d+)\]|Script[- ]?(\d+)|#(\d+)|\bS(\d+)\b)/i);
    if (numMatch) { const num = numMatch[1]||numMatch[2]||numMatch[3]||numMatch[4]; const sm = brandScripts.find(s => String(s.script_number) === num); if (sm) { matched.push({ ad, script: sm, method: 'pattern' }); found = true; } }
    if (!found) { const recMatch = name.match(/rec[A-Za-z0-9]{14,}/); if (recMatch) { const sm = brandScripts.find(s => s.id === recMatch[0]); if (sm) { matched.push({ ad, script: sm, method: 'record_id' }); found = true; } } }
    if (!found) unmatchedAds.push(ad);
  }

  brandResults.push({ brand_name: brandName, industry: brandIndustry, status: 'processing', adsCount: ads.length, scriptsCount: brandScripts.length, matched, unmatchedAds, brandScripts });

  if (unmatchedAds.length > 0) {
    const adList = unmatchedAds.map(a => `  Ad: ID=${a.ad_id}, Name="${a.ad_name}", Spend=$${a.spend.toFixed(0)}`).join('\n');
    const scriptList = brandScripts.map(s => { const hooks = [s.hook, s.hook_1, s.hook_2, s.hook_3].filter(Boolean).join(' | '); return `  Script: ID=${s.id}, Num=${s.script_number}, Hooks="${hooks}", Preview="${s.full_script.substring(0,200)}"`; }).join('\n');
    allUnmatchedSections.push(`BRAND: ${brandName}\nUnmatched Ads:\n${adList}\nScripts:\n${scriptList}`);
  }
}

const totalUnmatched = brandResults.reduce((sum, b) => sum + (b.unmatchedAds || []).length, 0);
let geminiPrompt = '';
if (totalUnmatched > 0 && allUnmatchedSections.length > 0) {
  geminiPrompt = JSON.stringify({ systemInstruction: { parts: [{ text: 'You are an ad-to-script matching engine for a UGC ad agency. Match Meta ads to their originating scripts by comparing ad names, hooks, copy structure, and messaging. Each ad can ONLY match scripts from its own brand. Return ONLY a valid JSON array.' }] }, contents: [{ role: 'user', parts: [{ text: `Match these Meta ads to the most likely originating script.\n\n${allUnmatchedSections.join('\n\n')}\n\nReturn a JSON array: [{"ad_id": "...", "script_id": "rec...", "confidence": 0.0-1.0, "reasoning": "brief explanation"}]\nOnly include matches with confidence >= 0.7. If no confident match, omit that ad.` }] }], generationConfig: { temperature: 0.2, maxOutputTokens: 4096, thinkingConfig: { thinkingBudget: 0 } } });
}

return [{ json: { brandResults: JSON.stringify(brandResults), geminiPrompt, unmatchedCount: totalUnmatched, totalAds, totalScripts, source: contexts[0]?.json?.source || 'unknown' } }];

// ============================================================
// Parse Gemini response, apply matches, build full summary
// Single item in → single item out (aggregated across all brands)
// ============================================================
const geminiResp = $input.first().json;
const prevData = $('Pattern Match + Build Gemini Prompt').first().json;
const brandResults = JSON.parse(prevData.brandResults || '[]');

// Parse Gemini matches
const geminiMatches = [];
try {
  const text = (geminiResp.candidates || [])[0]?.content?.parts?.[0]?.text || '';
  let cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
  try {
    const arrMatch = cleaned.match(/\[[\s\S]*\]/);
    const parsed = arrMatch ? JSON.parse(arrMatch[0]) : JSON.parse(cleaned);
    geminiMatches.push(...parsed);
  } catch (e) {
    const objPattern = /\{[^{}]*"ad_id"\s*:\s*"[^"]+"[^{}]*\}/g;
    const objs = cleaned.match(objPattern) || [];
    for (const o of objs) { try { geminiMatches.push(JSON.parse(o)); } catch (e2) {} }
  }
} catch (e) { /* parse failed */ }

// Apply Gemini matches to brand results
for (const br of brandResults) {
  if (br.status !== 'processing') continue;
  for (const m of geminiMatches) {
    if ((m.confidence || 0) < 0.7 || !m.ad_id || !m.script_id) continue;
    const ad = (br.unmatchedAds || []).find(a => a.ad_id === m.ad_id);
    const script = (br.brandScripts || []).find(s => s.id === m.script_id);
    if (ad && script && !(br.matched || []).find(x => x.ad?.ad_id === ad.ad_id)) {
      br.matched.push({ ad, script, method: 'gemini', confidence: m.confidence, reasoning: m.reasoning });
    }
  }
}

// Build updates + Slack summary for ALL brands
const allUpdates = [];
const brandLines = [];
const allTopPerformers = [];
let totalMatched = 0;

for (const br of brandResults) {
  const updates = [];
  const topPerformers = [];
  const underperformers = [];
  for (const match of (br.matched || [])) {
    const ad = match.ad; const script = match.script;
    if (!ad || !script) continue;
    let tier = 'Average';
    if (ad.roas >= 3.0 || ad.ctr >= 2.0) tier = 'Top Performer';
    else if (ad.roas >= 1.5 || ad.ctr >= 1.0) tier = 'Good';
    else if (ad.roas < 0.5 && ad.ctr < 0.5) tier = 'Underperformer';
    const conceptId = Array.isArray(script.concept_id) ? (script.concept_id[0] || '') : (script.concept_id || '');
    updates.push({ id: script.id, fields: { meta_ad_name: ad.ad_name, meta_ad_id: ad.ad_id, ad_spend: Math.round(ad.spend * 100) / 100, ad_ctr: Math.round(ad.ctr * 100) / 100, ad_roas: Math.round(ad.roas * 100) / 100, ad_impressions: ad.impressions, performance_tier: tier, _brand_name: br.brand_name, _concept_id: conceptId } });
    if (tier === 'Top Performer') topPerformers.push({ script_number: script.script_number, script_id: script.id, concept_id: conceptId, brand_name: br.brand_name, hook: script.hook, roas: ad.roas, ctr: ad.ctr, ad_name: ad.ad_name });
    if (tier === 'Underperformer') underperformers.push({ script_number: script.script_number, script_id: script.id, concept_id: conceptId, brand_name: br.brand_name, hook: script.hook, roas: ad.roas, ctr: ad.ctr });
  }
  allUpdates.push(...updates);
  totalMatched += (br.matched || []).length;
  allTopPerformers.push(...topPerformers);
  const pc = (br.matched || []).filter(m => m.method === 'pattern' || m.method === 'record_id').length;
  const gc = (br.matched || []).filter(m => m.method === 'gemini').length;
  const ec = (br.matched || []).filter(m => m.method === 'existing').length;
  if (br.status === 'processing') {
    let line = `:chart_with_upwards_trend: *${br.brand_name}* — ${(br.matched||[]).length}/${br.adsCount} ads matched to ${br.scriptsCount} scripts`;
    if (pc > 0) line += `\n   Pattern: ${pc}`;
    if (gc > 0) line += ` | Gemini: ${gc}`;
    if (ec > 0) line += ` | Existing: ${ec}`;
    const unm = br.adsCount - (br.matched||[]).length;
    if (unm > 0) line += `\n   :warning: ${unm} ads unmatched`;
    for (const tp of topPerformers) line += `\n   :star: *Script #${tp.script_number}* (${(tp.hook||'').substring(0,40)}) — ${tp.roas.toFixed(1)}x ROAS, ${tp.ctr.toFixed(1)}% CTR`;
    for (const up of underperformers) line += `\n   :small_red_triangle_down: Script #${up.script_number} — ${up.roas.toFixed(1)}x ROAS, ${up.ctr.toFixed(1)}% CTR`;
    brandLines.push(line);
  } else if (br.status === 'no_ads') {
    brandLines.push(`:white_circle: *${br.brand_name}* — No ads with spend in last 30 days`);
  } else if (br.status === 'no_scripts') {
    brandLines.push(`:white_circle: *${br.brand_name}* — No scripts found for this brand`);
  }
}

const slackMsg = `:arrows_counterclockwise: *Performance Sync Complete*\n\n${brandLines.join('\n\n')}\n\n*Summary:* ${totalMatched}/${prevData.totalAds} ads matched. ${allUpdates.length} script records updated.`;
const batches = [];
for (let i = 0; i < allUpdates.length; i += 10) batches.push(allUpdates.slice(i, i + 10));

return [{ json: { slackMsg, totalMatched, totalAds: prevData.totalAds, updateCount: allUpdates.length, batches: JSON.stringify(batches), batchCount: batches.length, topPerformers: JSON.stringify(allTopPerformers), brandSummaries: JSON.stringify(brandResults.map(br => ({ brand: br.brand_name, industry: br.industry || '', status: br.status === 'processing' ? 'synced' : br.status, matched: (br.matched||[]).length, ads: br.adsCount }))), source: prevData.source } }];

// ============================================================
// No-Gemini path: build updates from pattern matches only
// Single item in → single item out (aggregated across all brands)
// ============================================================
const prevData = $input.first().json;
const brandResults = JSON.parse(prevData.brandResults || '[]');

const allUpdates = [];
const brandLines = [];
const allTopPerformers = [];
let totalMatched = 0;

for (const br of brandResults) {
  const updates = [];
  const topPerformers = [];
  const underperformers = [];
  for (const match of (br.matched || [])) {
    const ad = match.ad; const script = match.script;
    if (!ad || !script) continue;
    let tier = 'Average';
    if (ad.roas >= 3.0 || ad.ctr >= 2.0) tier = 'Top Performer';
    else if (ad.roas >= 1.5 || ad.ctr >= 1.0) tier = 'Good';
    else if (ad.roas < 0.5 && ad.ctr < 0.5) tier = 'Underperformer';
    const conceptId = Array.isArray(script.concept_id) ? (script.concept_id[0] || '') : (script.concept_id || '');
    updates.push({ id: script.id, fields: { meta_ad_name: ad.ad_name, meta_ad_id: ad.ad_id, ad_spend: Math.round(ad.spend * 100) / 100, ad_ctr: Math.round(ad.ctr * 100) / 100, ad_roas: Math.round(ad.roas * 100) / 100, ad_impressions: ad.impressions, performance_tier: tier, _brand_name: br.brand_name, _concept_id: conceptId } });
    if (tier === 'Top Performer') topPerformers.push({ script_number: script.script_number, script_id: script.id, concept_id: conceptId, brand_name: br.brand_name, hook: script.hook, roas: ad.roas, ctr: ad.ctr, ad_name: ad.ad_name });
    if (tier === 'Underperformer') underperformers.push({ script_number: script.script_number, script_id: script.id, concept_id: conceptId, brand_name: br.brand_name, hook: script.hook, roas: ad.roas, ctr: ad.ctr });
  }
  allUpdates.push(...updates);
  totalMatched += (br.matched || []).length;
  allTopPerformers.push(...topPerformers);
  const pc = (br.matched || []).filter(m => m.method === 'pattern' || m.method === 'record_id').length;
  const ec = (br.matched || []).filter(m => m.method === 'existing').length;
  if (br.status === 'processing') {
    let line = `:chart_with_upwards_trend: *${br.brand_name}* — ${(br.matched||[]).length}/${br.adsCount} ads matched to ${br.scriptsCount} scripts`;
    if (pc > 0) line += `\n   Pattern: ${pc}`;
    if (ec > 0) line += ` | Existing: ${ec}`;
    const unm = br.adsCount - (br.matched||[]).length;
    if (unm > 0) line += `\n   :warning: ${unm} ads unmatched`;
    for (const tp of topPerformers) line += `\n   :star: *Script #${tp.script_number}* (${(tp.hook||'').substring(0,40)}) — ${tp.roas.toFixed(1)}x ROAS, ${tp.ctr.toFixed(1)}% CTR`;
    for (const up of underperformers) line += `\n   :small_red_triangle_down: Script #${up.script_number} — ${up.roas.toFixed(1)}x ROAS, ${up.ctr.toFixed(1)}% CTR`;
    brandLines.push(line);
  } else if (br.status === 'no_ads') {
    brandLines.push(`:white_circle: *${br.brand_name}* — No ads with spend in last 30 days`);
  } else if (br.status === 'no_scripts') {
    brandLines.push(`:white_circle: *${br.brand_name}* — No scripts found for this brand`);
  }
}

const slackMsg = `:arrows_counterclockwise: *Performance Sync Complete*\n\n${brandLines.join('\n\n')}\n\n*Summary:* ${totalMatched}/${prevData.totalAds} ads matched. ${allUpdates.length} script records updated.`;
const batches = [];
for (let i = 0; i < allUpdates.length; i += 10) batches.push(allUpdates.slice(i, i + 10));

return [{ json: { slackMsg, totalMatched, totalAds: prevData.totalAds, updateCount: allUpdates.length, batches: JSON.stringify(batches), batchCount: batches.length, topPerformers: JSON.stringify(allTopPerformers), brandSummaries: JSON.stringify(brandResults.map(br => ({ brand: br.brand_name, industry: br.industry || '', status: br.status === 'processing' ? 'synced' : br.status, matched: (br.matched||[]).length, ads: br.adsCount }))), source: prevData.source } }];

// Split batch updates into individual items for HTTP Request
const data = $input.first().json;
const batches = JSON.parse(data.batches || '[]');
if (batches.length === 0) return [{ json: { batchCount: 0 } }];
return batches.map(batch => ({ json: { batchBody: JSON.stringify({ records: batch }), batchSize: batch.length, batchCount: batches.length } }));

// ============================================================
// Build Gemini prompt to extract actionable learnings from
// the performance sync data (matched ads, tiers, metrics)
// Now includes brand_name, industry, script_id, concept_id
// and asks for brand-specific + agency-wide learnings
// ============================================================
const summary = $input.first().json;
const brandSummaries = JSON.parse(summary.brandSummaries || '[]');
const topPerformers = JSON.parse(summary.topPerformers || '[]');
const totalMatched = summary.totalMatched || 0;
const totalAds = summary.totalAds || 0;
const updateCount = summary.updateCount || 0;

// If no matches at all, skip learnings generation
if (totalMatched === 0) {
  return [{ json: {
    ...summary,
    learningsPrompt: '',
    skipLearnings: true,
    brandContextMap: '{}'
  } }];
}

// Build brand context map for downstream use (brand_name -> industry)
const brandContextMap = {};
for (const b of brandSummaries) {
  brandContextMap[b.brand] = { industry: b.industry || '' };
}

// Build a rich context string from the performance data
const brandCtx = brandSummaries.map(b => {
  return `Brand: ${b.brand} | Industry: ${b.industry || 'unknown'} | Status: ${b.status} | Ads: ${b.ads} | Matched: ${b.matched}`;
}).join('\n');

const topCtx = topPerformers.length > 0
  ? topPerformers.map(tp => {
    return `Script #${tp.script_number} [script_id=${tp.script_id || 'N/A'}, concept_id=${tp.concept_id || 'N/A'}] (Hook: "${(tp.hook || '').substring(0, 80)}") Brand: ${tp.brand_name || 'unknown'} - Ad: "${(tp.ad_name || '').substring(0, 80)}" - ROAS: ${tp.roas.toFixed(2)}x, CTR: ${tp.ctr.toFixed(2)}%`;
  }).join('\n')
  : 'No top performers identified this cycle.';

// Re-parse the full batches to get all tier data for richer analysis
const batches = JSON.parse(summary.batches || '[]');
const allUpdates = batches.flat();
const tierCounts = { 'Top Performer': 0, 'Good': 0, 'Average': 0, 'Underperformer': 0 };
const spendByTier = { 'Top Performer': 0, 'Good': 0, 'Average': 0, 'Underperformer': 0 };
const ctrByTier = { 'Top Performer': [], 'Good': [], 'Average': [], 'Underperformer': [] };
const roasByTier = { 'Top Performer': [], 'Good': [], 'Average': [], 'Underperformer': [] };

for (const u of allUpdates) {
  const tier = u.fields.performance_tier || 'Average';
  tierCounts[tier] = (tierCounts[tier] || 0) + 1;
  spendByTier[tier] = (spendByTier[tier] || 0) + (u.fields.ad_spend || 0);
  if (ctrByTier[tier]) ctrByTier[tier].push(u.fields.ad_ctr || 0);
  if (roasByTier[tier]) roasByTier[tier].push(u.fields.ad_roas || 0);
}

const avg = arr => arr.length > 0 ? (arr.reduce((a, b) => a + b, 0) / arr.length) : 0;

const tierSummary = Object.keys(tierCounts).map(tier => {
  const count = tierCounts[tier];
  if (count === 0) return null;
  return `${tier}: ${count} scripts, $${spendByTier[tier].toFixed(0)} total spend, avg CTR ${avg(ctrByTier[tier]).toFixed(2)}%, avg ROAS ${avg(roasByTier[tier]).toFixed(2)}x`;
}).filter(Boolean).join('\n');

const promptText = `You are an expert ad performance analyst for a UGC ad agency (Cosmisk). Analyze the following performance sync data and extract 3-8 actionable learnings.

IMPORTANT: You MUST generate TWO types of learnings:
1. **Brand-specific learnings** — Insights tied to a specific brand (e.g. "Wheelwash POV hooks got 3.2x ROAS"). Set brand_name to the brand name.
2. **Agency-wide learnings** — Patterns that appear generalizable across brands/industries. Set brand_name to "" (empty string).

PERFORMANCE SYNC RESULTS:
- Total ads analyzed: ${totalAds}
- Ads matched to scripts: ${totalMatched}
- Script records updated: ${updateCount}
- Sync timestamp: ${new Date().toISOString()}

BRAND BREAKDOWN:
${brandCtx}

PERFORMANCE TIER DISTRIBUTION:
${tierSummary}

TOP PERFORMERS:
${topCtx}

ALL MATCHED SCRIPT METRICS:
${allUpdates.map(u => {
  const f = u.fields;
  return `Script ${u.id} [brand=${f._brand_name || 'unknown'}, concept=${f._concept_id || 'N/A'}]: ad="${(f.meta_ad_name || '').substring(0, 60)}" spend=$${f.ad_spend} CTR=${f.ad_ctr}% ROAS=${f.ad_roas}x tier=${f.performance_tier}`;
}).join('\n')}

For each learning:
- If derived from a specific script, include its script_id and concept_id (if available)
- Brand-specific learnings MUST include the exact brand_name
- Agency-wide learnings MUST have brand_name as empty string
- Include the industry if known

Return ONLY valid JSON:
{
  "learnings": [
    {
      "title": "Short descriptive title (max 80 chars)",
      "category": "script_quality|hook_patterns|ad_performance|audience_insight|timing_pattern",
      "insight": "Detailed explanation of the learning with specific numbers",
      "confidence": 1-10,
      "brand_name": "BrandName or empty string for agency-wide",
      "industry": "industry or empty string",
      "script_id": "recXXX or empty string",
      "concept_id": "recXXX or empty string"
    }
  ]
}`;

const geminiBody = JSON.stringify({
  systemInstruction: {
    parts: [{ text: 'You are a performance analytics engine. Extract actionable learnings from ad performance data. Generate BOTH brand-specific learnings (tagged with brand_name) AND agency-wide learnings (brand_name empty). Return ONLY valid JSON, no markdown fences, no extra text.' }]
  },
  contents: [{
    role: 'user',
    parts: [{ text: promptText }]
  }],
  generationConfig: {
    temperature: 0.3,
    maxOutputTokens: 8192,
    thinkingConfig: { thinkingBudget: 0 }
  }
});

return [{ json: {
  ...summary,
  learningsPrompt: geminiBody,
  skipLearnings: false,
  brandContextMap: JSON.stringify(brandContextMap)
} }];

// ============================================================
// Parse Gemini learnings, dedup against existing, support
// confirmation bumping, brand tagging, script/concept linking
// ============================================================
const existingResp = $input.first().json;
const geminiResp = $('Gemini \u2014 Extract Learnings').first().json;
const upstreamData = $('Build Learnings Prompt').first().json;

// If learnings were skipped (no matched ads), pass through
if (upstreamData.skipLearnings) {
  return [{ json: { learningsBatchBody: '', learningsCount: 0, confirmBatchBody: '', confirmCount: 0, skipWrite: true } }];
}

// Parse brand context map for industry lookup
const brandContextMap = JSON.parse(upstreamData.brandContextMap || '{}');

// Parse existing learnings for dedup + confirmation bumping
const existingLearnings = [];
try {
  const records = existingResp.records || [];
  for (const r of records) {
    existingLearnings.push({
      id: r.id,
      title: (r.fields || {}).title || '',
      insight: (r.fields || {}).insight || '',
      brand_name: (r.fields || {}).brand_name || '',
      category: (r.fields || {}).category || '',
      times_confirmed: parseInt((r.fields || {}).times_confirmed) || 1,
      decay_score: parseFloat((r.fields || {}).decay_score) || 5,
      last_confirmed_at: (r.fields || {}).last_confirmed_at || '',
      confidence: parseInt((r.fields || {}).confidence) || 5
    });
  }
} catch (e) { /* fetch may have failed, proceed without dedup */ }

// Parse Gemini response
let newLearnings = [];
try {
  const text = (geminiResp.candidates || [])[0]?.content?.parts?.[0]?.text || '';
  let cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();
  const parsed = JSON.parse(cleaned);
  newLearnings = parsed.learnings || parsed || [];
  if (!Array.isArray(newLearnings)) newLearnings = [newLearnings];
} catch (e) {
  try {
    const text = (geminiResp.candidates || [])[0]?.content?.parts?.[0]?.text || '';
    let cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();
    const objPattern = /\{[^{}]*"title"\s*:\s*"[^"]+"[^{}]*\}/g;
    const objs = cleaned.match(objPattern) || [];
    for (const o of objs) { try { newLearnings.push(JSON.parse(o)); } catch (e2) {} }
  } catch (e2) { /* total parse failure */ }
}

// Similarity check: same brand + same pattern
function similar(a, b) {
  const wordsA = a.toLowerCase().split(/\s+/);
  const wordsB = b.toLowerCase().split(/\s+/);
  const common = wordsA.filter(w => wordsB.includes(w) && w.length > 3);
  return common.length / Math.max(wordsA.length, wordsB.length) > 0.5;
}

const validCategories = ['script_quality', 'hook_patterns', 'ad_performance', 'audience_insight', 'timing_pattern'];
const timestamp = new Date().toISOString();

const dedupedLearnings = [];
const confirmationBumps = [];  // existing records to PATCH
const usedExistingIds = new Set();

for (const learning of newLearnings) {
  if (!learning.title || !learning.insight) continue;

  const learningBrand = (learning.brand_name || '').trim();
  const learningIndustry = (learning.industry || '').trim() || (brandContextMap[learningBrand] || {}).industry || '';
  const confidence = Math.min(10, Math.max(1, parseInt(learning.confidence) || 5));

  // Check for similar existing learning with SAME brand (confirmation bumping)
  const matchingExisting = existingLearnings.find(existing => {
    if (usedExistingIds.has(existing.id)) return false;
    const sameBrand = (existing.brand_name || '') === learningBrand;
    return sameBrand && (similar(learning.title, existing.title) || similar(learning.insight, existing.insight));
  });

  if (matchingExisting) {
    // Confirmation bump: update existing record
    usedExistingIds.add(matchingExisting.id);
    confirmationBumps.push({
      id: matchingExisting.id,
      fields: {
        times_confirmed: matchingExisting.times_confirmed + 1,
        last_confirmed_at: timestamp,
        decay_score: confidence,
        insight: learning.insight.substring(0, 2000)
      }
    });
    continue;
  }

  // Also dedup within the current batch
  const isDupInBatch = dedupedLearnings.some(prev => prev.brand_name === learningBrand && similar(learning.title, prev.title));
  if (isDupInBatch) continue;

  const category = validCategories.includes(learning.category) ? learning.category : 'ad_performance';

  dedupedLearnings.push({
    title: learning.title.substring(0, 200),
    category,
    insight: learning.insight.substring(0, 2000),
    confidence,
    brand_name: learningBrand,
    industry: learningIndustry,
    script_id: (learning.script_id || '').trim(),
    concept_id: (learning.concept_id || '').trim()
  });
}

// Build NEW Airtable records
const newRecords = dedupedLearnings.map(l => {
  const fields = {
    title: l.title,
    source_agent: 'performance_sync',
    category: l.category,
    insight: l.insight,
    evidence: 'Based on Performance Sync run at ' + timestamp,
    confidence: l.confidence,
    decay_score: l.confidence,
    times_confirmed: 1,
    last_confirmed_at: timestamp,
    active: true,
    created_at: timestamp
  };
  if (l.brand_name) fields.brand_name = l.brand_name;
  if (l.industry) fields.industry = l.industry;
  if (l.script_id) fields.script_id = l.script_id;
  if (l.concept_id) fields.concept_id = l.concept_id;
  return { fields };
});

// Build confirmation bump PATCH body
const confirmBatches = [];
for (let i = 0; i < confirmationBumps.length; i += 10) {
  confirmBatches.push(confirmationBumps.slice(i, i + 10));
}
const confirmBatchBody = confirmBatches.length > 0 ? JSON.stringify({ records: confirmBatches[0] }) : '';

if (newRecords.length === 0 && confirmationBumps.length === 0) {
  return [{ json: { learningsBatchBody: '', learningsCount: 0, confirmBatchBody: '', confirmCount: 0, skipWrite: true } }];
}

// Batch new records into groups of 10
const newBatches = [];
for (let i = 0; i < newRecords.length; i += 10) {
  newBatches.push(newRecords.slice(i, i + 10));
}

return [{ json: {
  learningsBatchBody: newBatches.length > 0 ? JSON.stringify({ records: newBatches[0] }) : JSON.stringify({ records: [] }),
  learningsCount: newRecords.length,
  confirmBatchBody: confirmBatchBody,
  confirmCount: confirmationBumps.length,
  skipWrite: newRecords.length === 0 && confirmationBumps.length === 0
} }];
